mapper.select:
SELECT analysis_id
FROM analysis_data
WHERE analysis_batch_date = #{analysisBatchDate}
  AND product_bio = #{productBio}
  AND subbarcode = #{subbarcode}
  AND del_flag = '0'
ORDER BY analysis_id DESC
LIMIT 1

mapper.update:
UPDATE analysis_data
SET drive_status = #{driveStatus}, update_by = #{updateBy}, update_time = NOW()
WHERE analysis_id = #{analysisId}
